unit(5, "경험론과 칸트", 5, [4],
     ["로크·버클리·흄으로 이어지는 경험론의 흐름을 설명할 수 있다.", "흄의 인과 비판과 회의주의가 칸트에게 준 영향을 말할 수 있다.", "칸트 비판 철학의 구조(이론 이성·실천 이성·판단력)를 설명할 수 있다."],
     ["로크: 백지설, 단순 관념과 복합 관념, 제1성질과 제2성질", "버클리: 제1성질도 지각에 의존, '존재는 지각됨이다'", "흄: 인상과 관념, 인과 비판, 자아의 다발 이론, 회의주의", "칸트: '흄이 독단의 잠에서 깨웠다', 선험적 종합 판단, 감성과 오성의 형식", "현상과 물자체, 이성의 이율배반", "세 비판서: 『순수 이성 비판』, 『실천 이성 비판』, 『판단력 비판』"],
     ["경험론의 흐름은 '경험에서 출발하면 어디까지 확실히 알 수 있는가'를 점점 더 엄격하게 따진 과정입니다. 로크는 물체의 객관적 성질을 인정했고, 버클리는 그것마저 지각에 의존한다고 했으며, 흄은 인과와 자아까지 의심했습니다. 이 흐름이 칸트의 종합으로 이어지는 연결을 철학개론 4단원과 함께 정리하세요.",
      "칸트는 우리가 아는 것은 마음의 틀(시간·공간, 범주)을 거친 '현상'이고, 그 너머의 '물자체'는 알 수 없다고 했습니다. 그런데 도덕과 자유는 이론 이성으로 증명할 수 없지만 실천 이성의 요청으로 정당화된다고 보았습니다. 레벨1 윤리Ⅱ 챕터 6의 칸트 윤리가 이 구조 위에 서 있다는 점을 이해하세요."],
     [R(RUSSELL_HIST, "로크, 버클리, 흄, 칸트 장"), R(SEP("Kant's Critique of Metaphysics", "kant-metaphysics"), "개관"), L1R("c11", 6, "서양 근현대의 윤리 사상")],
     [fill(1, "로크는 크기·모양처럼 물체 자체에 있는 성질을 제{{1}}성질이라고 했습니다.", [["1", "일"]], "색·맛 같은 제2성질과 구별했습니다.", hint="숫자입니다."),
      fill(2, "칸트는 자신을 '독단의 잠에서 깨운' 철학자로 {{1}}을 꼽았습니다.", [["흄"]], "인과에 대한 흄의 비판이 계기였습니다.", hint="스코틀랜드 철학자입니다."),
      fill(3, "칸트는 인식의 틀을 거치지 않은 그 자체로서의 대상을 {{1}}라고 불렀습니다.", [["물자체"]], "현상과 대비되며 인식할 수 없습니다.", hint="'사물 그 자체'를 줄인 말입니다."),
      order(4, "다음 경험론·비판 철학자를 활동 시기 순으로 배열하세요.", ["로크", "버클리", "흄", "칸트"], [2, 0, 3, 1], "로크(17세기 후반) → 버클리(18세기 초) → 흄(18세기 중엽) → 칸트(18세기 후반) 순입니다.", hint="백지설의 철학자부터입니다.")]),
unit(6, "19세기 철학", 4, [5],
     ["헤겔의 변증법과 절대정신 개념을 설명할 수 있다.", "마르크스의 역사적 유물론을 말할 수 있다.", "쇼펜하우어·키르케고르·니체의 비합리주의와 공리주의를 비교할 수 있다."],
     ["독일 관념론: 피히테, 셸링, 헤겔(변증법, 정–반–합, 절대정신, 이성적인 것은 현실적)", "마르크스: 헤겔 변증법의 유물론적 전환, 토대와 상부 구조, 계급 투쟁", "쇼펜하우어: 의지와 표상으로서의 세계, 염세주의", "키르케고르: 실존, 단독자, 질적 변증법", "니체: '신은 죽었다', 힘에의 의지, 위버멘쉬, 영원 회귀, 가치의 전도", "영국: 공리주의(벤담·밀), 실증주의(콩트)"],
     ["헤겔은 역사를 정신이 자유를 실현해 가는 변증법적 과정으로 보았고, 마르크스는 이를 뒤집어 물질적 생산 관계가 역사를 움직인다고 보았습니다. '헤겔을 거꾸로 세웠다'는 말의 의미를 레벨1 윤리Ⅱ 챕터 8의 마르크스 사상과 연결해 설명해 보세요.",
      "니체는 기존의 도덕과 형이상학을 근본적으로 의심해 20세기 철학에 큰 영향을 주었습니다. '신은 죽었다'는 말이 종교에 대한 단순한 공격이 아니라 서양 문명의 가치 기반이 무너졌다는 진단이라는 점을 이해하고, 실존주의(7단원)와 어떻게 이어지는지 정리하세요."],
     [R(RUSSELL_HIST, "헤겔, 마르크스, 니체, 공리주의자 장"), R(SEP("Hegel", "hegel"), "개관"), L1R("c11", 8, "이상 사회와 사회사상")],
     [fill(1, "모순과 대립을 통해 더 높은 단계로 발전한다는 헤겔의 사유 방법은 {{1}}입니다.", [["변증법"]], "정–반–합으로 요약되곤 합니다.", hint="'대화의 기술'에서 온 말입니다."),
      fill(2, "경제적 토대가 정치·법·사상 같은 상부 구조를 결정한다는 마르크스의 역사관은 역사적 {{1}}론입니다.", [["유물"]], "헤겔의 관념론을 뒤집었습니다.", hint="'물질만 있음'입니다."),
      fill(3, "'신은 죽었다'고 선언하고 기존 가치를 뒤집는 위버멘쉬를 제시한 철학자는 {{1}}입니다.", [["니체"]], "힘에의 의지를 말했습니다.", hint="독일 철학자입니다."),
      fill(4, "세계의 본질을 맹목적인 의지로 보고 염세주의를 주장한 철학자는 {{1}}입니다.", [["쇼펜하우어"]], "불교와 인도 철학의 영향을 받았습니다.", hint="『의지와 표상으로서의 세계』를 썼습니다.")]),
unit(7, "20세기 철학", 5, [6],
     ["분석 철학의 탄생과 언어적 전회를 설명할 수 있다.", "현상학과 실존주의의 핵심 개념을 말할 수 있다.", "비판 이론, 구조주의·포스트구조주의, 실용주의의 문제의식을 비교할 수 있다."],
     ["분석 철학: 프레게(뜻과 지시체), 러셀(기술 이론), 전기 비트겐슈타인(『논리철학논고』), 논리 실증주의(검증 원리)", "후기 비트겐슈타인: 언어 게임, 의미는 사용", "현상학: 후설(사태 자체로, 판단 중지, 지향성), 하이데거(현존재, 세계–내–존재)", "실존주의: 사르트르(실존은 본질에 앞선다), 보부아르, 카뮈(부조리)", "프랑크푸르트학파(아도르노, 하버마스의 의사소통 행위), 구조주의(소쉬르, 레비스트로스), 포스트구조주의(푸코, 데리다)", "실용주의(퍼스, 제임스, 듀이), 롤스 이후 정치 철학"],
     ["20세기 철학은 크게 영미의 분석 철학과 유럽 대륙 철학으로 나뉩니다. 분석 철학은 언어와 논리의 명료화를, 대륙 철학은 의식·존재·역사·권력을 주로 다뤘습니다. 같은 문제(예: 의미란 무엇인가)를 두 전통이 어떻게 다르게 접근했는지 비교하면 현대 철학의 지도가 그려집니다.",
      "비트겐슈타인은 한 사람이 두 개의 철학을 남긴 드문 경우입니다. 전기에는 언어가 세계의 그림이라고, 후기에는 언어의 의미가 사용에 있다고 했습니다. 논리학 과목의 형식 언어와 일상 언어의 차이를 생각하며 두 시기의 차이를 정리해 보세요. 문화인류학개론과 미디어와 사회에서 본 구조주의·문화 연구도 이 단원의 사상과 이어집니다."],
     [R(RUSSELL_HIST, "논리 분석 철학 장"), R(SEP("Ludwig Wittgenstein", "wittgenstein"), "전기와 후기"), R(SEP("Phenomenology", "phenomenology"), "개관")],
     [fill(1, "단어의 의미는 그것이 쓰이는 방식에 있다며 '언어 게임' 개념을 제시한 후기 철학자는 {{1}}입니다.", [["비트겐슈타인"]], "전기에는 『논리철학논고』를 썼습니다.", hint="오스트리아 출신 철학자입니다."),
      fill(2, "'사태 자체로!'를 내세우며 의식의 지향성을 연구한 현상학의 창시자는 {{1}}입니다.", [["후설"]], "하이데거의 스승입니다.", hint="독일 철학자입니다."),
      fill(3, "'실존은 본질에 앞선다'고 말한 프랑스 실존주의 철학자는 {{1}}입니다.", [["사르트르"]], "레벨1 윤리Ⅱ 챕터 6에서 배웠습니다.", hint="『존재와 무』를 썼습니다."),
      fill(4, "경험으로 참·거짓을 확인할 수 있는 명제만 의미가 있다는 논리 실증주의의 기준은 {{1}} 원리입니다.", [["검증"]], "형이상학 명제를 무의미하다고 보았습니다.", hint="'검사하여 증명함'입니다.")]),
unit(8, "중국 철학 ①: 선진 제자백가", 4, [],
     ["춘추 전국 시대의 사회 변동과 제자백가의 등장을 설명할 수 있다.", "유가·도가·묵가·법가·명가의 핵심 주장을 비교할 수 있다.", "맹자와 순자의 인성론 논쟁을 말할 수 있다."],
     ["배경: 주 왕실의 쇠퇴, 사회 혼란, 사(士) 계층의 성장", "유가: 공자(인·예·정명), 맹자(성선설·사단·왕도), 순자(성악설·예치)", "도가: 노자(도·무위자연), 장자(제물론·소요유)", "묵가: 묵자(겸애·비공·절용, 천지)", "법가: 상앙·한비자(법·술·세)", "명가: 공손룡(백마비마), 혜시 — 개념과 논리의 문제"],
     ["제자백가는 '혼란한 세상을 어떻게 바로잡을 것인가'라는 같은 질문에 대한 다른 답입니다. 레벨1 윤리Ⅱ 챕터 2·4에서 유가와 도가를 배웠다면, 이 단원에서는 묵가와 명가까지 넓혀 각 학파가 인간 본성, 사회 질서, 언어를 어떻게 보았는지 철학적 논증의 관점에서 비교하세요.",
      "명가의 '흰 말은 말이 아니다(백마비마)'는 궤변처럼 들리지만 개념의 내포와 외연을 구별하는 논리적 문제입니다. 논리학 4단원의 정언 명제와 연결해, '흰 말'과 '말'이라는 개념의 관계를 설명해 보세요. 중국 철학에도 논리학의 전통이 있었음을 보여 주는 사례입니다."],
     [R(FUNG, "자학 시대 장"), R(SEP("Mohism", "mohism"), "묵가 개관"), L1R("c11", 2, "유교 윤리 사상"), G2R("world-history", "east-asian-history", 1, "동양사개설 1단원 선진 시대")],
     [fill(1, "차별 없는 사랑을 주장하고 침략 전쟁에 반대한 학파는 {{1}}가입니다.", [["묵"]], "겸애와 비공을 내세웠습니다.", hint="창시자 묵자의 성에서 왔습니다."),
      fill(2, "인간의 본성은 악하므로 예로 바로잡아야 한다고 본 유학자는 {{1}}입니다.", [["순자"]], "맹자의 성선설과 대립했습니다.", hint="'순'으로 시작합니다."),
      fill(3, "'흰 말은 말이 아니다'라는 논변으로 개념의 차이를 따진 명가의 사상가는 {{1}}입니다.", [["공손룡"]], "중국 고대 논리학의 대표입니다.", hint="성이 '공손'입니다."),
      written(4, "맹자의 성선설과 순자의 성악설을 비교하고, 두 입장이 정치 사상에서 어떻게 달라지는지 설명해 보세요.",
              [["맹자", "성선"], ["순자", "성악"], ["사단", "본성", "선한 마음"], ["예", "교화", "왕도", "덕"]], 3,
              "맹자는 사람에게 측은지심 같은 사단이 있어 본성이 선하다고 보고, 그 선한 마음을 넓히는 덕치와 왕도 정치를 주장했습니다. 순자는 사람의 본성은 이익을 좇는 악한 것이라 보고, 성인이 만든 예로 본성을 바로잡는 교화와 예치를 강조했습니다. 순자의 생각은 제자인 한비자의 법가로 이어졌습니다.")]),
